<div class="page-actions"><div><h2>Cause Areas</h2><p>Cause areas are separate from fundraising campaigns. Manage the public cause cards and their images here.</p></div></div><div class="management-layout"><section class="admin-panel sticky-form"><div class="panel-head"><h3>Cause Editor</h3><button class="outline-link mini" type="button" data-cause-reset>New Cause</button></div><form method="post" enctype="multipart/form-data" action="<?=url('admin/causes/save')?>" class="admin-form" data-cause-form><?=csrf_field()?><input type="hidden" name="id"><label class="full"><span>Cause Name *</span><input name="name" required maxlength="120"></label><label><span>Icon / Symbol</span><input name="icon" maxlength="40" value="♡"></label><label><span>Display Order</span><input type="number" name="sort_order" value="0"></label><label class="full"><span>Description</span><textarea name="description" rows="5" maxlength="600"></textarea></label><label class="full"><span>Cause Image</span><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"><small class="helper">Recommended 1200 × 800 px (3:2). Automatically cover-fitted.</small></label><label class="toggle-line full"><input type="checkbox" name="is_active" value="1" checked><span>Active on public Causes page</span></label><button class="admin-btn full">Save Cause Area</button></form></section><section class="cause-admin-grid"><?php foreach($causes as $c):$payload=e(json_encode(['id'=>$c['id'],'name'=>$c['name'],'icon'=>$c['icon'],'sort_order'=>$c['sort_order'],'description'=>$c['description'],'is_active'=>(int)$c['is_active']],JSON_HEX_APOS|JSON_HEX_QUOT));?><article class="cause-admin-card admin-panel"><div class="cause-admin-image"><?php if($c['image_path']):?><img src="<?=e(safe_image($c['image_path'],'images/demo/cause-education.jpg'))?>" alt=""><?php else:?><span><?=e($c['icon']?:'♡')?></span><?php endif;?></div><div><span class="status-badge <?=$c['is_active']?'active':'inactive'?>"><?=$c['is_active']?'Active':'Inactive'?></span><h3><?=e($c['name'])?></h3><p><?=e($c['description']??'')?></p><div class="card-admin-actions"><button class="outline-link" type="button" data-cause-edit='<?=$payload?>'>Edit</button><form method="post" action="<?=url('admin/causes/toggle')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><button class="outline-link"><?=$c['is_active']?'Deactivate':'Activate'?></button></form><form method="post" action="<?=url('admin/causes/delete')?>" data-confirm="Delete this cause area?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><button class="danger-link">Delete</button></form></div></div></article><?php endforeach;?></section></div>

